@RestController
@RequestMapping("/api/v1/appointments")
@Validated
@SecurityRequirement(name = "Bearer Authentication")
public class AppointmentController {

    @Autowired
    private AppointmentService appointmentService;

    @PostMapping
    @PreAuthorize("hasRole('STUDENT') or hasRole('PSYCHOLOGIST')")
    public ResponseEntity<AppointmentResponseDto> createAppointment(
        @Valid @RequestBody CreateAppointmentRequestDto request,
        Authentication authentication
    ) {
        try {
            AppointmentResponseDto response = appointmentService
                .createAppointment(request, authentication.getName());
            return ResponseEntity.status(HttpStatus.CREATED).body(response);
        } catch (AppointmentConflictException e) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, e.getMessage());
        }
    }

    @GetMapping
    @PreAuthorize("hasRole('STUDENT') or hasRole('PSYCHOLOGIST') or hasRole('ADMIN')")
    public ResponseEntity<List<AppointmentResponseDto>> getAppointments(
        Authentication authentication,
        @RequestParam(required = false) String status
    ) {
        List<AppointmentResponseDto> appointments = appointmentService
            .getAppointmentsByUser(authentication.getName(), status);
        return ResponseEntity.ok(appointments);
    }
}

